{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Category_Target_vs_Achievement AS WITH Category_Age_Mapping AS ( SELECT DISTINCT TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS COLLECTION, CATEGORY_AGE FROM maplemonk.zouk_secondary_sales_Consolidated WHERE CATEGORY_AGE IS NOT NULL ), Category_Level_Target AS ( SELECT TRIM(UPPER(t.Marketplace)) AS Marketplace, TRIM(UPPER(t.Category)) AS PRODUCT_CATEGORY, fsm.Collection, UPPER(fsm.Product_Type) AS Product_Type, DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Target_Date, CAST(REPLACE(t.Target,\",\",\"\") AS INT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM maplemonk.Zouk_Category_Level_Target t LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(CATEGORY) ORDER BY IFNULL(collection, \'\') DESC) = 1 ) fsm ON LOWER(fsm.CATEGORY) = LOWER(t.CATEGORY) CROSS JOIN UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n QUALIFY ROW_NUMBER() OVER ( PARTITION BY Target_Date, Marketplace, PRODUCT_CATEGORY, Collection ORDER BY Product_Type ) = 1 ), Daily_Achievements AS ( SELECT TRIM(UPPER(s.Marketplace)) AS Marketplace, TRIM(UPPER(s.PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(s.COLLECTION)) AS Collection, TRIM(UPPER(s.product_type)) AS Product_Type, DATE(s.Order_Date) AS Achievement_Date, SUM( CASE WHEN LOWER(s.marketplace) LIKE ANY (\'myntra%\',\'flipkart\') AND LOWER(s.collection) LIKE \'gifting%\' THEN 0 ELSE IFNULL(s.QUANTITY, 0) END ) + COUNT(DISTINCT CASE WHEN LOWER(s.marketplace) LIKE ANY (\'myntra%\',\'flipkart\') AND LOWER(s.collection) LIKE \'gifting%\' THEN CONCAT(Order_ID, \'_\', TRIM(UPPER(s.Marketplace)), \'_\', TRIM(UPPER(s.Collection))) ELSE NULL END ) AS Quantity, SUM(IFNULL(s.Selling_Price, 0)) AS Achievement FROM maplemonk.zouk_secondary_sales_Consolidated s WHERE NOT (LOWER(IFNULL(ORDER_STATUS,\'\')) LIKE \'%cancel%\' OR LOWER(IFNULL(FINAL_SHIPPING_STATUS,\'\')) LIKE \'%cancel%\') AND DATE(s.Order_Date) < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1, 2, 3, 4, 5 ), Daily_Spends AS ( SELECT TRIM(UPPER(Marketplace)) AS Marketplace, TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS Collection, TRIM(UPPER( CASE WHEN PRODUCT_TYPE IS NULL OR TRIM(PRODUCT_TYPE) = \'\' THEN COLLECTION ELSE PRODUCT_TYPE END )) AS Product_Type, DATE(Date) AS Spend_Date, SUM(IFNULL(Spend, 0)) AS Spend, SUM(IFNULL(Sales,0)) AS Sales, SUM(IFNULL(Secondary_Trade_Margin,0)) AS Secondary_TRADE_MARGIN, SUM(IFNULL(Returns,0)) AS Returns, SUM(IFNULL(gst,0)) AS gst, SUM(IFNULL(secondary_TradeMargin_GST,0)) AS Secondary_Trade_Margin_GST, SUM(IFNULL(COGS, 0)) AS COGS FROM maplemonk.zouk_secondary_pandl WHERE DATE(Date) < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1, 2, 3, 4, 5 ), Combined_Data AS ( SELECT COALESCE(COALESCE(dt.Target_Date, da.Achievement_Date), ds.Spend_Date) AS Date, COALESCE(COALESCE(dt.Marketplace, da.Marketplace), ds.Marketplace) AS Marketplace, COALESCE(COALESCE(dt.PRODUCT_CATEGORY, da.PRODUCT_CATEGORY), ds.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, COALESCE(COALESCE(dt.Collection, da.Collection),ds.Collection) AS Collection, COALESCE(COALESCE(dt.Product_Type, da.Product_Type), ds.Product_Type) AS Product_Type, da.Quantity, dt.Target, dt.days_Remaining, dt.no_of_days, COALESCE(da.Achievement, 0) AS Achievement, COALESCE(ds.Spend, 0) AS Spend, COALESCE(ds.Sales, 0) AS Sales, COALESCE(ds.SECONDARY_TRADE_MARGIN,0) AS SECONDARY_TRADE_MARGIN, COALESCE(ds.Returns,0) AS Returns, COALESCE(ds.gst,0) AS gst, COALESCE(ds.Secondary_Trade_Margin_GST,0) AS Secondary_Trade_Margin_GST, COALESCE(ds.COGS, 0) AS COGS FROM Category_Level_Target dt FULL OUTER JOIN Daily_Achievements da ON TRIM(dt.Marketplace) = TRIM(da.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(da.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(da.Collection) AND dt.Target_Date = da.Achievement_Date FULL OUTER JOIN Daily_Spends ds ON TRIM(dt.Marketplace) = TRIM(ds.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(ds.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(ds.Collection) AND dt.Target_Date = ds.Spend_Date ), Final_Data AS ( SELECT cd.Date, cd.Marketplace, cd.PRODUCT_CATEGORY, cd.Collection, cd.Product_Type, cd.Target, cd.Achievement, cd.Spend, cd.Quantity, cd.Sales, cd.SECONDARY_TRADE_MARGIN, cd.Secondary_Trade_Margin_GST, cd.Returns, cd.gst, cd.COGS, cd.days_Remaining, cd.no_of_days, mm.FINAL_MARKETPLACE, mm.Marketplace_Segments, upper(mm.Channel) AS Channel, ca.Category_Age, CASE WHEN mm.Marketplace IS NULL THEN \'Missing in Marketplace Mapping\' ELSE \'Found\' END AS Mapping_Status FROM Combined_Data cd LEFT JOIN ( SELECT * FROM maplemonk.Zouk_New_Marketplace_Mapping QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(marketplace)) ORDER BY 1) = 1 ) mm ON LOWER(TRIM(cd.Marketplace)) = LOWER(TRIM(mm.Marketplace)) LEFT JOIN Category_Age_Mapping ca ON cd.PRODUCT_CATEGORY = ca.PRODUCT_CATEGORY AND cd.Collection = ca.COLLECTION ) SELECT Date, Marketplace, PRODUCT_CATEGORY, Collection, Product_Type, Target, Achievement, Spend, Quantity, Sales, SECONDARY_TRADE_MARGIN, Secondary_Trade_Margin_GST, Returns, gst, COGS, SAFE_DIVIDE((Sales - Returns - gst - SECONDARY_TRADE_MARGIN - COGS), Sales) AS Gross_Margin_Percent, days_Remaining, no_of_days, FINAL_MARKETPLACE, Marketplace_Segments, Channel, CATEGORY_AGE FROM Final_Data ORDER BY Date, Marketplace, PRODUCT_CATEGORY",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            